package com.commercecore.payment;import jakarta.validation.Valid;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.*;import org.springframework.http.*;
@RestController @RequestMapping("/api/v1/orders/{orderId}/payments") public class CustomerPaymentController{final PaymentService service;public CustomerPaymentController(PaymentService s){service=s;}@PostMapping public ResponseEntity<PaymentDtos.PaymentResponse>pay(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID orderId,@RequestHeader("Idempotency-Key")String key,@Valid@RequestBody PaymentDtos.PaymentRequest req){return ResponseEntity.status(HttpStatus.CREATED).body(service.pay(UUID.fromString(jwt.getSubject()),orderId,key,req));}@GetMapping public List<PaymentDtos.PaymentResponse>list(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID orderId){return service.customerPayments(UUID.fromString(jwt.getSubject()),orderId);}@GetMapping("/{paymentId}")public PaymentDtos.PaymentResponse get(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID paymentId){return service.get(UUID.fromString(jwt.getSubject()),paymentId);}}
